function validate([nums, s, d]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 robots.';
  if (typeof s !== 'string' || s.length !== nums.length) return 's needs exactly one direction per robot.';
  if (!/^[LR]*$/.test(s)) return "s may contain only 'L' and 'R'.";
  if (nums.some(v => !Number.isInteger(v) || v < -2e9 || v > 2e9)) return 'Each start is an integer between -2*10^9 and 2*10^9.';
  if (new Set(nums).size !== nums.length) return 'The starting points must all be different.';
  if (!Number.isInteger(d) || d < 0 || d > 1e9) return 'd is an integer between 0 and 10^9.';
  return null;
}

