function sumDistance(nums, s, d) {
  const MOD = 1e9 + 7;
  const positions = nums.map((start, i) => (s[i] === 'R' ? start + d : start - d));
  positions.sort((a, b) => a - b);

  let answer = 0;
  let prefix = 0;
  for (let i = 0; i < positions.length; i++) {
    const gain = i * positions[i] - prefix;
    answer = (answer + gain) % MOD;
    prefix += positions[i];
  }
  return answer;
}

