function sumDistance(nums, s, d) {
  // Real bouncing, simulated event by event on doubled coordinates (time in half-seconds),
  // so every meeting happens at a whole step and positions stay integers.
  const order = nums.map((_, i) => i).sort((a, b) => nums[a] - nums[b]);
  const pos = order.map(i => 2 * nums[i]);
  const dir = order.map(i => (s[i] === 'R' ? 1 : -1));
  let remaining = 2 * d;
  while (remaining > 0) {
    let step = remaining;
    for (let k = 0; k + 1 < pos.length; k++) {
      if (dir[k] === 1 && dir[k + 1] === -1) step = Math.min(step, (pos[k + 1] - pos[k]) / 2);
    }
    for (let k = 0; k < pos.length; k++) pos[k] += dir[k] * step;
    remaining -= step;
    for (let k = 0; k + 1 < pos.length; k++) {
      if (pos[k] === pos[k + 1] && dir[k] === 1 && dir[k + 1] === -1) { dir[k] = -1; dir[k + 1] = 1; }
    }
  }
  let total = 0n;
  for (let a = 0; a < pos.length; a++)
    for (let b = a + 1; b < pos.length; b++) total += BigInt(Math.abs(pos[a] - pos[b]) / 2);
  return Number(total % 1000000007n);
}

