function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 6);
  const span = size === 'large' || rand() < 0.2 ? 2000000000 : 12;
  const seen = new Set();
  const nums = [];
  while (nums.length < n) {
    const value = Math.floor(rand() * (2 * span + 1)) - span;
    if (!seen.has(value)) { seen.add(value); nums.push(value); }
  }
  const s = nums.map(() => (rand() < 0.5 ? 'L' : 'R')).join('');
  const d = size === 'large' || rand() < 0.2 ? Math.floor(rand() * 1000000001) : Math.floor(rand() * 10);
  return [nums, s, d];
}
